const heute = DateTime.now().setZone('Europe/Berlin').toISODate();
const seiten = $('Projekte (Papierkram)').all().map(i => i.json || {});
const alle = seiten.flatMap(s => Array.isArray(s.entries) ? s.entries : []);
const mitBudget = alle.filter(p => p.record_state === 'active'
  && ((p.budget_type === 'money' && Number(p.budget_money) > 0) || (p.budget_type === 'working_time' && Number(p.budget_time) > 0))
  && (!p.start_date || p.start_date <= heute));
return mitBudget.length ? mitBudget.map(p => ({ json: { id: p.id } })) : [{ json: { id: 0, keine: true } }];

const heute = DateTime.now().setZone('Europe/Berlin').toISODate();
const keine = !!$('Budgetprojekte wählen').first().json.keine;
const listeFehler = $('Projekte (Papierkram)').all().some(i => i.json && i.json.error);
const det = $('Projektdetails (Papierkram)').all().map(i => i.json || {}).filter(p => p.type === 'project');
const zs = $('Projektzeiten (Papierkram)').all().map(i => i.json || {});
const eintr = zs.flatMap(z => Array.isArray(z.entries) ? z.entries : []);
const fehler = listeFehler || (!keine && (det.length === 0 || zs.some(z => z.error) || $('Projektdetails (Papierkram)').all().some(i => i.json && i.json.error)));
const r2 = v => Math.round(v * 100) / 100;
const projekte = [];
for (const p of det) {
  const sek = eintr.filter(t => t.project_id === p.id && t.record_state !== 'archived' && !t.unbillable).reduce((a, t) => a + Number(t.billable_duration ?? t.duration ?? 0), 0);
  const stunden = sek / 3600;
  const x = { id: p.id, projekt: p.name, kunde: (p.customer && p.customer.name) || '', budget_art: p.budget_type === 'money' ? 'Geld' : 'Zeit', start: p.start_date, ende: p.end_date, laufzeit_beendet: !!(p.end_date && p.end_date < heute), stunden: r2(stunden) };
  if (p.budget_type === 'money') {
    const satz = Number(p.default_proposition && p.default_proposition.price);
    x.budget_eur = Number(p.budget_money);
    x.stundensatz_eur = satz > 0 ? satz : null;
    x.verbraucht_eur = satz > 0 ? r2(stunden * satz) : null;
    x.prozent = satz > 0 ? Math.round(stunden * satz / x.budget_eur * 1000) / 10 : null;
    x.rest_eur = satz > 0 ? r2(x.budget_eur - stunden * satz) : null;
  } else {
    x.budget_stunden = Number(p.budget_time);
    x.prozent = Math.round(stunden / x.budget_stunden * 1000) / 10;
    x.rest_stunden = r2(x.budget_stunden - stunden);
  }
  projekte.push(x);
}
projekte.sort((a, b) => (b.prozent ?? -1) - (a.prozent ?? -1));
return [{ json: { stand: DateTime.now().setZone('Europe/Berlin').toFormat('dd.LL.yyyy HH:mm'), grundlage: 'Abrechenbare Zeiten aus Papierkram; Geldbudgets mit dem Standard-Stundensatz des Projekts gerechnet.', keine_budgetprojekte: keine, fehler, projekte } }];
